function startPresence() {
  // Beat ONLY while the tab is visible - every other interval in the app already
  // does this, but presence didn't, so a backgrounded/installed app kept pinging
  // "I'm here" and stayed "online", which made the server suppress incoming-message
  // pushes. A hidden app goes quiet, ages out of the active window, and starts
  // getting notified. On return to the app, beat at once so you show online again.
  const beat = () => { if (document.hidden) return; api('/api/presence', { method: 'POST' }).catch(() => {}); };
  beat();
  setInterval(beat, 60000);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) beat(); });
}
// The Contacts badge is a genuine notification: the number of people waiting for
// you to accept their invitation to connect. It is NOT a running total of your
// contacts (that just looked like an unread count sitting on the button). Unread
// chat and the online list still feed Home's "People" section, not this badge.
const friendPending = () => ((state.friendStatus || {}).incoming || 0) + ((state.friendStatus || {}).unread || 0);
// The hamburger badge counts connection requests; unread messages get their own
// message icon in the top bar. (Robin, 2026-10-14.)
const navReq = () => (state.friendStatus || {}).incoming || 0;
const navUnread = () => (state.friendStatus || {}).unread || 0;
// Tap the top-bar message icon: if just one person messaged, jump straight into
// that chat; otherwise open the Messages page to pick. (Robin, 2026-10-14; the
// fallback now lands on the Messages inbox rather than the people hub.)
function openMessages() {
  const by = (state.friendStatus && state.friendStatus.unreadBy) || {};
  const ids = Object.keys(by).filter((k) => by[k] > 0);
  if (ids.length === 1) {
    const id = Number(ids[0]);
    const f = ((state.friends && state.friends.friends) || []).find((x) => x.id === id);
    openChat(id, (f && f.name) || 'Message');
    return;
  }
  openMessagesPage().catch(() => {});
}
// Admin home alert: open Admin on the Invites tab, where the requests live. The
// alert persists until each request is actually dealt with (invited/dismissed),
// not merely seen. (Robin, 2026-10-14.)
function openRequests() {
  state.admin = state.admin || {}; state.admin.tab = 'invites';
  openAdmin().catch(() => {});
}
// Remove a join request from the list (after inviting them, or to clear spam).
// Keeps the home alert count in step so it clears once they're all handled.
async function dismissRequest(id) {
  try { await api('/api/admin/invite-requests/dismiss', { method: 'POST', body: JSON.stringify({ id: Number(id) }) }); } catch {}
  if (state.admin) state.admin.requests = (state.admin.requests || []).filter((r) => String(r.id) !== String(id));
  if (state.inviteReq) state.inviteReq.count = (state.admin && state.admin.requests || []).length;
  renderAdmin();
}
// Unread LifeFold MESSAGES (not friend requests) - the signal we make loud.
const unreadMsgs = () => ((state.friendStatus || {}).unread || 0);
// Unread messages from one person, for the badge on their row.
const unreadFrom = (id) => (((state.friendStatus || {}).unreadBy) || {})[id] || 0;
// Name of a LifeFold contact by id, from whatever's loaded (friends list, then
// the online roster). Falls back to a generic label.
function friendName(id) {
  const f = ((state.friends && state.friends.friends) || []).find((x) => String(x.id) === String(id));
  if (f && f.name) return f.name;
  const o = ((state.friendStatus && state.friendStatus.online) || []).find((x) => String(x.id) === String(id));
  return (o && o.name) || '';
}
async function refreshFriendStatus() {
  try {
    const prevUnread = (state.friendStatus && state.friendStatus.unreadBy) || {};
    const hadBaseline = !!state.friendStatus;   // don't ping for unread that was already there on first load
    const r = await api('/api/friends/status');
    const sig = JSON.stringify([r.incoming || 0, r.unread || 0, r.unreadBy || {}, (r.online || []).map((o) => o.id).sort()]);
    const changed = sig !== state.__friendSig; state.__friendSig = sig;
    state.friendStatus = { incoming: r.incoming || 0, online: r.online || [], unread: r.unread || 0, unreadBy: r.unreadBy || {}, friends: r.friends || 0 };
    // Ping when a contact's unread rises (a new message) - unless you're already
    // in that chat. A toast alerts you wherever you are in LifeFold.
    if (hadBaseline) {
      const openWith = state.chat && state.chat.with;
      Object.keys(r.unreadBy || {}).forEach((id) => {
        if ((r.unreadBy[id] || 0) > (prevUnread[id] || 0) && Number(id) !== Number(openWith)) {
          toast(`💬 ${friendName(id) || 'A LifeFold contact'} messaged you`);
        }
      });
    }
    if (changed) { renderNav(); renderTabs(); }   // only when the badge actually changes - a needless rebuild can steal a nav tap. renderTabs keeps the header message alert live.
    // Refresh Home's People section on a real change - but never while the user is
    // typing (e.g. in the notepad), which a full re-render would interrupt.
    const ae = document.activeElement; const editing = ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable);
    if (changed && state.view && !editing) {
      if (state.view.type === 'home') renderHome();
      else if (state.view.type === 'daybookpeople') renderLifeFoldPeople();   // online-first list stays live
      else if (state.view.type === 'messages') refreshMessages();   // new messages / read state stay live
    }
  } catch {}
}
function startFriendStatusPoll() {
  if (window.__friendStatusT) return;
  refreshFriendStatus();
  window.__friendStatusT = setInterval(() => { if (!document.hidden) refreshFriendStatus(); }, 90000);
}
// Home "People" section: whether it shows, and its contents (who's online + a
// nudge when someone wants to connect). Toggle lives in Settings → Appearance.
const peopleOn = () => { try { return localStorage.getItem('life.home.people') !== '0'; } catch { return true; } };
function peopleHtml() {
  const st = state.friendStatus;
  if (!st) { refreshFriendStatus(); return '<div class="home-empty" style="padding:6px 0">Loading…</div>'; }
  const online = st.online || []; const pending = st.incoming || 0;
  let html = '';
  if (pending) html += `<button class="people-nudge" data-open-contacts>👋 ${pending} ${pending === 1 ? 'person wants' : 'people want'} to connect</button>`;
  if (online.length) {
    html += `<div class="people-list">${online.map((f) => `<button class="people-row" data-friend-chat="${f.id}" data-friend-name="${esc(f.name)}" title="Message ${esc(f.name)}"><span class="fr-av online">${esc(initial(f.name || '?'))}</span><span class="people-name">${esc(f.name)}</span><span class="people-msg">💬</span></button>`).join('')}</div>`;
  } else if (!pending) {
    html += '<div class="home-empty">No one online right now. <button class="people-link" data-open-contacts>Open Contacts</button></div>';
  }
  return html;
}
// Chat with a friend: a slide-in panel that polls for new messages while open.
let chatPoll = null;
async function openChat(id, name) {
  state.chat = { with: Number(id), name, messages: [] };
  renderChat(); await loadChat();
  if (chatPoll) clearInterval(chatPoll);
  // Paused while the tab is in the background: a 4s poll running behind a phone's
  // lock screen is a battery cost for nothing. Reading the chat marks it read on
  // the server, so the badge clears as the poll runs.
  chatPoll = setInterval(() => {
    if (!state.chat) { clearInterval(chatPoll); chatPoll = null; return; }
    if (!document.hidden) loadChat();
  }, 4000);
}
async function loadChat() {
  if (!state.chat) return;
  const to = state.chat.with;
  // getMessages marks them read on the server; mirror that locally so the badge
  // drops the moment you open the chat, not at the next 90s status poll.
  if (state.friendStatus && unreadFrom(to)) {
    state.friendStatus.unread = Math.max(0, state.friendStatus.unread - unreadFrom(to));
    delete state.friendStatus.unreadBy[to];
    renderNav();
  }
  try {
    const r = await api(`/api/messages?with=${to}`);
    if (!state.chat || state.chat.with !== to) return;   // switched chats mid-request
    // Compare the content, not the count. A count misses a message that arrives in
    // the same poll as one being removed, and it can't see a message change at all.
    const sig = (list) => (list || []).map((m) => `${m.id || ''}:${m.body}:${m.reaction || ''}`).join('\u0000');
    if (sig(r.messages) !== sig(state.chat.messages)) { state.chat.messages = r.messages; renderChatMessages(); }
  } catch {}
}
// A small, curated emoji set for the chat composer - enough for everyday warmth
