    practices: modOn('today') ? `<button class="nav-item ${v.type === 'practices' || v.type === 'tracker' ? 'on' : ''}" data-open-practices><span class="nav-ic">☯</span><span class="nav-lbl">${t('nav.practices')}</span></button>` : '',
