// A flat, importance-ordered single column of clear tool buttons - the mobile
// drawer. No group boxes, no 2-up grid: just tap what you want. (The desktop
// sidebar keeps the grouped grid.)
// Today is deliberately NOT in the mobile drawer - the day planner doesn't work
// well on a phone, so it's left off the mobile menu. (Robin.)
const MNAV_DEFAULT = ['mail', 'notes', 'calendar', 'tasks', 'contacts', 'messages', 'practices', 'wellbeing', 'areas', 'insights', 'goals', 'reviews', 'connect', 'daybook', 'financial', 'finSpending', 'finPortfolio', 'finTracker', 'finAdvice', 'saved'];
// The user's saved drawer order, with any new tools appended in the default spot.
function mobileNavOrder() {
  let saved = [];
  try { saved = JSON.parse(localStorage.getItem('life.nav.morder') || '[]'); } catch {}
  saved = Array.isArray(saved) ? saved.filter((k) => MNAV_DEFAULT.includes(k)) : [];
  // One-time (2026-10-20): lift Contacts to directly under Tasks for anyone who
  // already had a saved drawer order, so it matches the new default above. Guarded
  // by a flag so it runs once and never fights a later manual reorder. (Robin.)
  try {
    if (!localStorage.getItem('life.nav.contactsUnderTasks')) {
      if (saved.length && saved.includes('contacts') && saved.includes('tasks')) {
        saved = saved.filter((k) => k !== 'contacts');
        saved.splice(saved.indexOf('tasks') + 1, 0, 'contacts');
        localStorage.setItem('life.nav.morder', JSON.stringify(saved));
      }
      localStorage.setItem('life.nav.contactsUnderTasks', '1');
    }
  } catch {}
  // One-time (2026-10-28): lift Life Spaces to directly under Reflection
  // (wellbeing) for anyone with a saved drawer order, matching the new default.
  // Guarded so it runs once and never fights a later manual reorder. (Robin.)
  try {
    if (!localStorage.getItem('life.nav.areasUnderReflect')) {
      if (saved.length && saved.includes('areas') && saved.includes('wellbeing')) {
        saved = saved.filter((k) => k !== 'areas');
        saved.splice(saved.indexOf('wellbeing') + 1, 0, 'areas');
        localStorage.setItem('life.nav.morder', JSON.stringify(saved));
      }
      localStorage.setItem('life.nav.areasUnderReflect', '1');
    }
  } catch {}
  // Slot any default item missing from a saved order into its NATURAL place (just
  // after the previous default item that's present), rather than dumping newer
  // tools at the very bottom - so e.g. Contacts sits right under Pages.
  const order = [...saved];
  MNAV_DEFAULT.forEach((k, i) => {
    if (order.includes(k)) return;
    let at = order.length;
    for (let j = i - 1; j >= 0; j--) { const idx = order.indexOf(MNAV_DEFAULT[j]); if (idx >= 0) { at = idx + 1; break; } }
    order.splice(at, 0, k);
  });
  return order;
}
function saveMobileNavOrder(arr) { try { localStorage.setItem('life.nav.morder', JSON.stringify(arr)); } catch {} }
function navMobileListHtml(v) {
  const NI = navItems(v);
  // Each button rides in a row with a drag grip so the drawer can be reordered.
  const list = mobileNavOrder().map((k) => NI[k] ? `<div class="mnav-row" data-mnav-id="${k}"><span class="mnav-grip" data-mnav-grip aria-hidden="true">⠿</span>${NI[k]}</div>` : '').filter(Boolean).join('');
  // Force monochrome ("text") presentation on every icon glyph by appending the
  // VS15 selector - some glyphs (✉ ☯ ☀ ☺ …) otherwise render as full-colour
  // emoji that ignore our accent colour, and font-variant-emoji isn't honoured in
  // the Brave app's engine. VS15 is ignored on plain-text glyphs, so it's safe
  // for all of them. (Robin.)
  return `<nav class="nav-mlist">${list.replace(/(<span class="nav-ic">)([^<]+)(<\/span>)/g, (_, a, g, z) => a + g + '︎' + z)}</nav>`;
}
function navGridHtml(v) {
  const NI = navItems(v);
  // Each group is collapsible, in the same chevron-header style as the Starred /
  // Recent / Life Spaces sections, with its open/closed state remembered. (Robin.)
  const grp = (key, label, items) => {
    const on = items.filter(Boolean);
    if (!on.length) return '';
    const ck = 'grp.' + key;
    const collapsed = !!state.nav.collapsed[ck];
    const head = label ? `<div class="nav-grp nav-grp-h" data-sec-toggle="${ck}" title="${collapsed ? 'Expand' : 'Collapse'}"><span class="nav-chev">${collapsed ? '▸' : '▾'}</span><span class="nav-grp-t">${esc(label)}</span></div>` : '';
    return `<section class="nav-sec-box">${head}${collapsed ? '' : `<div class="nav-sec-items">${on.join('')}</div>`}</section>`;
  };
  // Home + Mail pinned, then Robin's mind-map branches - Daily / Meaningful /
  // People / General Tools. There's no "Capture" band: the make-a-new verbs live
  // in the "+ New" menu (breadcrumb row) and the Home buttons instead.
  // Home and Mail each sit in their own small rounded box (one grid column each,
  // side by side) so the pinned pair reads like the section boxes below it.
  const leadBox = (item) => item ? `<section class="nav-sec-box nav-lead-box">${item}</section>` : '';
  // Tools leads with Home (top-left), then the mains, and ends with Discover
  // (moved out of the Today group). Today keeps the day-planning trio below. (Robin.)
  return `<div class="nav-grid">
    ${grp('main', t('nav.grp.main'), [NI.home, NI.mail, NI.notes, NI.calendar, NI.tasks, NI.areas, NI.goals, NI.reviews, NI.saved, NI.discover])}
    ${grp('daily', t('nav.grp.daily'), [NI.today, NI.tracker, NI.practices])}
    ${peopleBox(v)}
    ${grp('money', t('nav.grp.money'), [NI.financial, NI.finSpending, NI.finPortfolio, NI.finAdvice])}
    ${grp('wellbeing', t('nav.grp.wellbeing'), [NI.wellbeing, NI.reflect, NI.coaching, NI.dreams, NI.compass, NI.iching, NI.spirit, NI.horoscope, NI.meditation, NI.insights])}
    ${grp('reviews', 'Reviews', [NI.rvAll, NI.rvDaily, NI.rvWeekly, NI.rvMonthly, NI.rvQuarterly, NI.rvYearly])}
  </div>`;
}
