// ── Toolbox: Focus, a plain countdown Timer, and Daily Practices ─────────
// The toolbox is a row of equal feature boxes; tap one to open its tool below.
const TBX_TOOLS = [
  { k: 'focus', ic: '⏱', label: 'Focus', desc: 'Pomodoro sessions for deep work', panel: () => pomoPanel() },
  { k: 'timer', ic: '⏲', label: 'Timer', desc: 'A simple countdown for anything', panel: () => timerPanel() },
  { k: 'tracker', ic: '✓', label: 'Practices', desc: 'Your practices, streaks and history', panel: () => trackerPanel() },
];
function tbxToolBadge(k) {
  return (k === 'focus' && pomo.running) ? `<span class="tbx-run js-pomo-time">${pomoFmt(pomoRemaining())}</span>`
    : (k === 'timer' && timerState.running) ? `<span class="tbx-run js-timer-time">${timerFmt(timerRemaining())}</span>`
    : (k === 'med' && medState.running) ? `<span class="tbx-run js-med-time">${medFmt(medRemaining())}</span>` : '';
}
function tbxActive() { try { return localStorage.getItem('life.toolbox.active') || ''; } catch { return ''; } }
function tbxOpen(k) { const cur = tbxActive(); try { localStorage.setItem('life.toolbox.active', cur === k ? '' : k); } catch {} if (state.view && state.view.type === 'toolbox') renderToolbox(); }
// Toolbox is its own tool (own sidebar button); it no longer lives on Home.
function openToolbox() { state.view = { type: 'toolbox' }; renderNav(); renderToolbox(); }
function renderToolbox() {
  const active = tbxActive();
  const cards = TBX_TOOLS.map((t) => { const badge = tbxToolBadge(t.k); return `<button class="tbx-card ${active === t.k ? 'on' : ''} ${badge ? 'running' : ''}" data-tbx-open="${t.k}">
      <span class="tbx-card-ic">${t.ic}</span>
      <span class="tbx-card-t">${t.label}</span>
      <span class="tbx-card-d">${t.desc}</span>
      ${badge || ''}
    </button>`; }).join('');
  const open = TBX_TOOLS.find((t) => t.k === active);
  $('#pane').innerHTML = `${pageCrumb(t('nav.timer'))}<div class="pane-head"><h1>🧰 ${t('nav.timer')}</h1></div>
    <div class="tbx-grid">${cards}</div>
    ${open ? `<div class="tbx-panel tbx-${open.k}"><div class="tbx-panel-h"><span class="tbx-ic">${open.ic}</span>${open.label}</div>${open.panel()}</div>` : '<p class="tbx-hint">Pick a tool to open it.</p>'}`;
}

// ── plain countdown Timer ───────────────────────────────────────────────
const TIMER_QUICK = [5, 10, 15, 25, 45];
let timerState = (() => { try { const t = JSON.parse(localStorage.getItem('life.timer')); if (t && typeof t.dur === 'number') return { area: null, ...t }; } catch {} return { label: '', area: null, running: false, endAt: null, remaining: 600, dur: 600 }; })();
function saveTimer() { try { localStorage.setItem('life.timer', JSON.stringify(timerState)); } catch {} }
function timerRemaining() { return (timerState.running && timerState.endAt) ? Math.max(0, Math.round((timerState.endAt - Date.now()) / 1000)) : timerState.remaining; }
const timerFmt = (s) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
let timerTicker = null;
function timerEnsureTicker() {
  if (timerTicker) return;
  timerTicker = setInterval(() => {
    if (!timerState.running) return;
    const r = timerRemaining();
    document.querySelectorAll('.js-timer-time').forEach((el) => { el.textContent = timerFmt(r); });
    if (r <= 0) {
      timerState.running = false; timerState.endAt = null; timerState.remaining = timerState.dur; saveTimer();
      logTimerSession(Math.max(1, Math.round(timerState.dur / 60)), timerState.label, timerState.area);
      timerChime(); const what = (timerState.label || '').trim();
      toast(`⏲ Timer done${what ? ` - ${what}` : ''}`); try { navigator.vibrate && navigator.vibrate([200, 100, 200]); } catch {}
      if (state.view && state.view.type === 'home') renderHome();
      else if (state.view && state.view.type === 'toolbox') renderToolbox();
    }
  }, 500);
}
function timerChime() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const o = ctx.createOscillator(); const g = ctx.createGain();
    o.connect(g); g.connect(ctx.destination); o.type = 'sine'; o.frequency.value = 880;
    g.gain.setValueAtTime(0.001, ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.2, ctx.currentTime + 0.02);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.9);
    o.start(); o.stop(ctx.currentTime + 0.95);
  } catch {}
}
function timerPanel() {
  const r = timerRemaining();
  const areaOpts = `<option value="">No lifespace</option>` + editableAreas().map((a) => `<option value="${a.id}" ${timerState.area === a.id ? 'selected' : ''}>${esc(a.title || 'Untitled')}${sharedTag(a)}</option>`).join('');
  return `<div class="tbx-cols"><div class="tbx-main"><div class="tmr ${timerState.running ? 'running' : ''}">
      <div class="tmr-time js-timer-time">${timerFmt(r)}</div>
      <input class="sel tmr-label" data-timer-label placeholder="What are you working on?" value="${esc(timerState.label || '')}" autocomplete="off">
      <label class="tmr-area-l"><span>Life Space</span><select class="sel" data-timer-area>${areaOpts}</select></label>
      <div class="tmr-quick">${TIMER_QUICK.map((m) => `<button class="tmr-q ${timerState.dur === m * 60 ? 'on' : ''}" data-timer-set="${m}">${m}m</button>`).join('')}</div>
      <div class="tmr-custom"><span class="tmr-custom-l">Custom</span><input class="sel tmr-cnum" id="timer-min" type="number" min="0" max="1440" inputmode="numeric" value="${Math.floor(timerState.dur / 60)}" title="Minutes"><span class="tmr-colon">:</span><input class="sel tmr-cnum" id="timer-sec" type="number" min="0" max="59" inputmode="numeric" value="${String(timerState.dur % 60).padStart(2, '0')}" title="Seconds"><button class="ghost tmr-set" data-timer-custom>Set</button></div>
      <div class="tmr-ctrls"><button class="add-btn wide" data-timer-toggle>${timerState.running ? 'Pause' : (r < timerState.dur ? 'Resume' : 'Start')}</button><button class="ghost pomo-reset" data-timer-reset title="Reset">↺</button></div>
    </div></div><aside class="tbx-side">${sessionsListHtml(timerSessions(), 'Finish a timer and it appears here.')}</aside></div>`;
}
function timerToggle() {
  if (timerState.running) { timerState.remaining = timerRemaining(); timerState.running = false; timerState.endAt = null; }
  else { if (timerRemaining() <= 0) timerState.remaining = timerState.dur; timerState.endAt = Date.now() + timerRemaining() * 1000; timerState.running = true; timerEnsureTicker(); }
  saveTimer(); reTools();
}
function timerReset() { timerState.running = false; timerState.endAt = null; timerState.remaining = timerState.dur; saveTimer(); reTools(); }
function timerSet(min) { timerState.dur = min * 60; timerState.running = false; timerState.endAt = null; timerState.remaining = min * 60; saveTimer(); reTools(); }
// Any exact length: minutes + seconds from the custom inputs.
function timerSetCustom() {
  const mi = document.getElementById('timer-min'), se = document.getElementById('timer-sec');
  const m = Math.max(0, Math.min(1440, Math.floor(Number(mi && mi.value) || 0)));
  const s = Math.max(0, Math.min(59, Math.floor(Number(se && se.value) || 0)));
  const total = m * 60 + s; if (total < 1) { toast('Set at least one second'); return; }
  timerState.dur = total; timerState.running = false; timerState.endAt = null; timerState.remaining = total; saveTimer(); reTools();
}
if (timerState.running) timerEnsureTicker();

// ── Meditation timer (built for zazen) ───────────────────────────────────
// A calm sit with a real bell: three gongs to open and to close (the last of the
// three fuller and longer), and an optional soft bell at intervals. The bell is
// synthesised - inharmonic partials with a long decay, a keisu rather than a beep.
// Three bell voices to choose from; the close drops lower and rings longer.
const BELL_TIMBRES = [{ name: 'Deep', base: 236 }, { name: 'Temple', base: 320 }, { name: 'Bright', base: 432 }];
const MED_SHIMMER_LEAD = 25;   // seconds of shimmer before the closing gong
let medState = (() => {
  const d = { running: false, endAt: null, remaining: 2400, dur: 2400, interval: 10, bell: 1, gongs: 3, shimmer: true };
  try { const t = JSON.parse(localStorage.getItem('life.med')); if (t && typeof t.dur === 'number') { d.dur = t.dur; d.remaining = t.dur; d.interval = t.interval || 0; if ([0, 1, 2].includes(t.bell)) d.bell = t.bell; if (t.gongs >= 1 && t.gongs <= 6) d.gongs = t.gongs; d.shimmer = t.shimmer !== false; } } catch {}
  return d;
})();
let medFired = new Set(); let medShimmerDone = false;
function saveMed() { try { localStorage.setItem('life.med', JSON.stringify({ dur: medState.dur, interval: medState.interval, bell: medState.bell, gongs: medState.gongs, shimmer: medState.shimmer })); } catch {} }
function medRemaining() { return (medState.running && medState.endAt) ? Math.max(0, Math.round((medState.endAt - Date.now()) / 1000)) : medState.remaining; }
const medFmt = (s) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const medBase = () => (BELL_TIMBRES[medState.bell] || BELL_TIMBRES[1]).base;
// One struck bell. Inharmonic partials (bell ratios), each decaying at its own
// rate, plus a brief strike shimmer. Warm, not shrill; `when` schedules ahead.
let medAudioCtx = null;
function medCtx() {
  try { if (!medAudioCtx) medAudioCtx = new (window.AudioContext || window.webkitAudioContext)(); if (medAudioCtx.state === 'suspended') medAudioCtx.resume().catch(() => {}); } catch {}
  return medAudioCtx;
}
function medBell({ base = medBase(), gain = 0.5, decay = 6, when = 0 } = {}) {
  const ctx = medCtx(); if (!ctx) return;
  const t0 = ctx.currentTime + when;
  const master = ctx.createGain(); master.connect(ctx.destination); master.gain.setValueAtTime(gain, t0);
  const partials = [[1.0, 1.0, 1.0], [2.02, 0.62, 0.82], [2.74, 0.42, 0.62], [3.76, 0.28, 0.46], [5.42, 0.18, 0.32], [8.21, 0.1, 0.22]];
  partials.forEach(([r, amp, dk]) => {
    const o = ctx.createOscillator(); const g = ctx.createGain(); o.type = 'sine'; o.frequency.value = base * r;
    o.connect(g); g.connect(master); const d = Math.max(0.4, decay * dk);
    g.gain.setValueAtTime(0.0001, t0); g.gain.exponentialRampToValueAtTime(amp, t0 + 0.006); g.gain.exponentialRampToValueAtTime(0.0001, t0 + d);
    o.start(t0); o.stop(t0 + d + 0.1);
  });
  try { const o2 = ctx.createOscillator(); const g2 = ctx.createGain(); o2.type = 'triangle'; o2.frequency.value = base * 5.4; o2.connect(g2); g2.connect(master); g2.gain.setValueAtTime(0.0001, t0); g2.gain.exponentialRampToValueAtTime(gain * 0.28, t0 + 0.004); g2.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.28); o2.start(t0); o2.stop(t0 + 0.32); } catch {}
}
// A run of n bells, ~2.7s apart. The closing run drops the last one lower/fuller.
function medGongSeq(n, end) {
  const base = medBase(); n = Math.max(1, Math.min(6, n || 3));
  for (let i = 0; i < n; i++) {
    const when = i * 2.7; const last = i === n - 1;
    if (end && last) medBell({ base: base * (n > 1 ? 0.72 : 0.82), gain: 0.66, decay: n > 1 ? 13 : 11, when });
    else medBell({ base, gain: 0.52, decay: 6.5, when });
  }
}
function medStartGongs() { medGongSeq(medState.gongs, false); }
function medEndGongs() { medGongSeq(medState.gongs, true); }
// A soft high shimmer a little before the end - a gentle "coming to a close" cue.
function medShimmer() {
  const ctx = medCtx(); if (!ctx) return;
  const t0 = ctx.currentTime; const base = medBase() * 4;
  const master = ctx.createGain(); master.connect(ctx.destination);
  master.gain.setValueAtTime(0.0001, t0); master.gain.exponentialRampToValueAtTime(0.13, t0 + 0.9); master.gain.exponentialRampToValueAtTime(0.0001, t0 + 3.4);
  [1, 1.5, 2.01, 2.63].forEach((r, i) => {
    const o = ctx.createOscillator(); const g = ctx.createGain(); o.type = 'sine'; o.frequency.value = base * r; g.gain.value = 0.5;
    const lfo = ctx.createOscillator(); const lg = ctx.createGain(); lfo.type = 'sine'; lfo.frequency.value = 4.5 + i * 1.3; lg.gain.value = 0.45; lfo.connect(lg); lg.connect(g.gain);
    o.connect(g); g.connect(master); o.start(t0); lfo.start(t0); o.stop(t0 + 3.5); lfo.stop(t0 + 3.5);
  });
}
let medTicker = null;
function medEnsureTicker() {
  if (medTicker) return;
  medTicker = setInterval(() => {
    if (!medState.running) return;
    const r = medRemaining(); const elapsed = medState.dur - r;
    document.querySelectorAll('.js-med-time').forEach((el) => { el.textContent = medFmt(r); });
    if (medState.interval > 0) {
      const step = medState.interval * 60;
      for (let m = step; m < medState.dur - 8; m += step) { if (elapsed >= m && !medFired.has(m)) { medFired.add(m); medBell({ gain: 0.44, decay: 5.5 }); } }
    }
    if (medState.shimmer && !medShimmerDone && r <= MED_SHIMMER_LEAD && r > 1) { medShimmerDone = true; medShimmer(); }
    if (r <= 0) {
      medState.running = false; medState.endAt = null; medState.remaining = medState.dur; saveMed(); medReleaseWake();
      logMedSession(Math.max(1, Math.round(medState.dur / 60)));
      medEndGongs(); toast('🧘 Sit complete'); try { navigator.vibrate && navigator.vibrate([120, 80, 120]); } catch {}
      if (state.view && state.view.type === 'toolbox') renderToolbox();
      else if (state.view && state.view.type === 'meditation') renderMeditation();
    }
  }, 250);
}
const reMed = () => { const v = state.view && state.view.type; if (v === 'toolbox') renderToolbox(); else if (v === 'meditation') renderMeditation(); };
// Keep the screen awake through a sit, so it doesn't sleep (and mute the bells)
// mid-meditation. The lock drops when the tab is hidden, so re-take it on return.
let medWakeLock = null;
async function medAcquireWake() { try { if ('wakeLock' in navigator) medWakeLock = await navigator.wakeLock.request('screen'); } catch {} }
function medReleaseWake() { try { if (medWakeLock) { medWakeLock.release(); medWakeLock = null; } } catch {} }
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible' && medState.running && !medWakeLock) medAcquireWake(); });
function medToggle() {
  if (medState.running) { medState.remaining = medRemaining(); medState.running = false; medState.endAt = null; medReleaseWake(); }
  else {
    const fresh = medRemaining() >= medState.dur;
    if (medRemaining() <= 0) medState.remaining = medState.dur;
    medState.endAt = Date.now() + medRemaining() * 1000; medState.running = true;
    medFired = new Set(); medShimmerDone = false; medCtx(); medAcquireWake();
    if (fresh) medStartGongs();
    medEnsureTicker();
  }
  saveMed(); reMed();
}
function medReset() { medState.running = false; medState.endAt = null; medState.remaining = medState.dur; medReleaseWake(); saveMed(); reMed(); }
function medSet(min) { medState.dur = min * 60; medState.running = false; medState.endAt = null; medState.remaining = min * 60; saveMed(); reMed(); }
function medSetInterval(min) { medState.interval = min; saveMed(); reMed(); }
function medSetCustom() {
  const mi = document.getElementById('med-min'); const m = Math.max(1, Math.min(180, Math.floor(Number(mi && mi.value) || 0)));
  medState.dur = m * 60; medState.running = false; medState.endAt = null; medState.remaining = m * 60; saveMed(); reMed();
}
function medSetIntervalCustom() {
  const mi = document.getElementById('med-int-min'); const m = Math.max(1, Math.min(120, Math.floor(Number(mi && mi.value) || 0)));
  medState.interval = m; saveMed(); reMed();
}
function medSetBell(i) { medState.bell = i; saveMed(); medCtx(); medBell({ gain: 0.5, decay: 6 }); reMed(); }   // preview on pick
function medSetGongs(n) { medState.gongs = Math.max(1, Math.min(6, n)); saveMed(); reMed(); }
const MED_PRESETS = [15, 30, 40];
const MED_INTERVALS = [[0, 'Off'], [10, '10 min'], [15, '15 min'], [20, '20 min']];
function medPanel() {
  const r = medRemaining(); const running = medState.running; const dur = medState.dur;
  const known = MED_INTERVALS.some(([v]) => v === medState.interval);
  const optRow = (label, vals) => `<div class="med-opt"><span class="med-opt-l">${label}</span><span class="med-opt-vals">${vals}</span></div>`;
  const bells = BELL_TIMBRES.map((b, i) => `<button class="med-chip ${medState.bell === i ? 'on' : ''}" data-med-bell="${i}" title="Hear it">${b.name}</button>`).join('');
  const gongs = [1, 3].map((n) => `<button class="med-chip ${medState.gongs === n ? 'on' : ''}" data-med-gongs="${n}">${n}</button>`).join('')
    + `<input class="sel med-num" id="med-gongs-num" type="number" min="1" max="6" inputmode="numeric" value="${medState.gongs}" title="How many gongs" data-med-gongs-input>`;
  const intervals = MED_INTERVALS.map(([v, l]) => `<button class="med-chip ${medState.interval === v ? 'on' : ''}" data-med-interval="${v}">${l}</button>`).join('')
    + `<input class="sel med-num" id="med-int-min" type="number" min="1" max="120" inputmode="numeric" value="${known ? '' : medState.interval}" placeholder="min" title="Custom minutes" data-med-int-input>`;
  const today = dayKey(new Date());
  const medSide = `<aside class="tbx-side">
    <div class="med-notes-box"><div class="sess-hist-h">Today's note</div><textarea class="sel med-notes-ta" data-med-note placeholder="A few words about this sit, if you like…">${esc(medNoteFor(today))}</textarea></div>
    ${sessionsListHtml(medSessions(), 'Finish a sit and it appears here.')}</aside>`;
  return `<div class="tbx-cols"><div class="tbx-main"><div class="med ${running ? 'running' : ''}">
      <div class="med-stage"><div class="med-orb"></div><div class="med-time js-med-time">${medFmt(r)}</div></div>
      <div class="med-presets">${MED_PRESETS.map((m) => `<button class="med-preset ${dur === m * 60 ? 'on' : ''}" data-med-set="${m}">${m} min</button>`).join('')}<span class="med-custom"><input class="sel med-cnum" id="med-min" type="number" min="1" max="180" inputmode="numeric" value="${Math.round(dur / 60)}" title="Minutes"><button class="ghost med-cset" data-med-custom>Set</button></span></div>
      <div class="med-opts">
        ${optRow('Bell', bells)}
        ${optRow('Opening &amp; closing gongs', gongs)}
        ${optRow('Intermittent gong', intervals)}
        <label class="med-opt med-shimmer"><span class="med-opt-l">Shimmer before the end</span><input type="checkbox" data-med-shimmer ${medState.shimmer ? 'checked' : ''}></label>
      </div>
      <div class="med-ctrls"><button class="add-btn wide med-go" data-med-toggle>${running ? 'Pause' : (r < dur ? 'Resume' : 'Begin')}</button><button class="ghost med-reset" data-med-reset title="Reset">↺</button></div>
      <div class="med-note">${medState.gongs} bell${medState.gongs === 1 ? '' : 's'} to open and close${medState.interval ? `, one every ${medState.interval} min` : ''}${medState.shimmer ? ', a shimmer as the end nears' : ''}. Keep the screen awake for the bells.</div>
    </div></div>${medSide}</div>`;
}
if (medState.running) medEnsureTicker();

// ── Daily Practices (shared with the Today tool via `activities`) ─────────
// The list of practices lives in the shared `activities` model, grouped by lane
// (your life-area categories), so editing it here shows in the Today tool and
// vice-versa. The daily ticks are ours, kept per-user in a kv setting.
const dayKey = (d) => d.toISOString().slice(0, 10);
// dayKey() is UTC (toISOString), so the day arithmetic here MUST be UTC too, or in
// a +HH timezone the whole 7-day window slips back a day and today drops off the
// end (which is exactly what made the Tracker show yesterday on the right and never
// fill "today"). setUTCDate keeps every key consistent with dayKey.
function trackerLast7() { const out = []; const d = new Date(); for (let i = 6; i >= 0; i--) { const x = new Date(d); x.setUTCDate(d.getUTCDate() - i); out.push(dayKey(x)); } return out; }
// A 7-day window ENDING on endISO (inclusive), so the Tracker can step back and
// forward through past weeks rather than being pinned to the last seven days.
function trackerWindow(endISO) { const out = []; const e = new Date(endISO + 'T00:00:00Z'); for (let i = 6; i >= 0; i--) { const x = new Date(e); x.setUTCDate(e.getUTCDate() - i); out.push(dayKey(x)); } return out; }
let practicesLoaded = false;
async function loadPractices(force) {
  if (practicesLoaded && !force && state.practices) return state.practices;
  try {
    const [a, m, areas] = await Promise.all([
      api('/api/activities'),
      api('/api/kv/practice_marks').catch(() => ({ value: null })),
      (state.areas && state.areas.length) ? Promise.resolve(state.areas) : api('/api/blocks?kind=area').catch(() => []),
    ]);
    let marks = {}; try { marks = m && m.value ? JSON.parse(m.value) : {}; } catch {}
    state.areas = (areas || []).slice().sort((x, y) => (x.title || '').localeCompare(y.title || ''));
    state.practices = { activities: a.activities || [], lanes: a.lanes || [], marks };
    practicesLoaded = true;
  } catch { state.practices = state.practices || { activities: [], lanes: [], marks: {} }; }
  return state.practices;
}
// ── practice scheduling helpers (Today redesign) ──────────────────────
const prcHHMM = (m) => (m == null || m === '') ? '' : `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
// A practice's page (by its stored area id), or null.
const practiceArea = (a) => a && a.area ? (state.areas || []).find((x) => x.id === a.area) : null;
// ── cadence + tracking (per practice AND per page) ───────────────
// The one cadence list, shared by the area check-in and each practice's aim.
const PRESET_CADS = [['1d', 'every day'], ['2d', 'every other day'], ['3d', 'every 3 days'], ['2w', 'twice a week'], ['1w', 'once a week'], ['14d', 'every 2 weeks']];
const parseCadence = (c) => { const m = String(c || '').match(/^(\d+)([dw])$/); return m ? { n: Number(m[1]), unit: m[2], raw: c } : null; };
function cadenceLabel(c) { const p = parseCadence(c); if (!p) return ''; if (p.unit === 'w') return p.n === 1 ? 'Once a week' : `${p.n}× a week`; return p.n === 1 ? 'Every day' : p.n === 2 ? 'Every other day' : `Every ${p.n} days`; }
const daysBetweenStr = (a, b) => Math.round((Date.parse(b + 'T00:00') - Date.parse(a + 'T00:00')) / 86400000);
// The days (YYYY-MM-DD) a practice was ticked, most-recent first.
function prcMarkedDays(id) {
  if (!state.practices) return [];
  const pre = `${id}:`; const out = [];
  for (const k in state.practices.marks) if (k.indexOf(pre) === 0 && state.practices.marks[k]) out.push(k.slice(pre.length));
  return out.sort().reverse();
}
// A page counts as "kept alive" on any day ANY of its tracked practices was
// ticked - so the union of its practices' marked days.
function areaMarkedDays(areaId) {
  const set = new Set();
  (state.practices.activities || []).filter((a) => a.area === areaId && a.tracked).forEach((a) => prcMarkedDays(a.id).forEach((d) => set.add(d)));
  return [...set].sort().reverse();
}
// On-track status for a set of marked days against a cadence. Robin dislikes red,
// so "slipping" is a gentle amber, never a scold.
function cadenceStatus(daysDesc, cadence) {
  const today = dayKey(new Date());
  const cad = parseCadence(cadence);
  const lastDone = daysDesc[0] || null;
  const doneToday = lastDone === today;
  const daysSince = lastDone ? daysBetweenStr(lastDone, today) : Infinity;
  if (!cad) return { status: doneToday ? 'ontrack' : 'none', label: lastDone ? (doneToday ? 'done today' : `${daysSince}d ago`) : 'not yet', streak: dailyStreak(daysDesc, today) };
  if (cad.unit === 'd') {
    let status, label;
    if (doneToday) { status = 'ontrack'; label = 'done today'; }
    else if (daysSince <= cad.n - 1) { status = 'ontrack'; label = `done ${daysSince}d ago`; }
    else if (daysSince === cad.n) { status = 'due'; label = 'due today'; }
    else { status = 'slipping'; label = lastDone ? `${daysSince}d ago` : 'not yet'; }
    return { status, label, streak: cadenceStreak(daysDesc, cad, today) };
  }
  const weekCount = daysDesc.filter((d) => daysBetweenStr(d, today) < 7).length;
  const status = weekCount >= cad.n ? 'ontrack' : (weekCount > 0 ? 'building' : 'slipping');
  return { status, label: `${weekCount} of ${cad.n} this week`, streak: weekCount };
}
// A page's check-in status, said forwards: are you on track, and how many
// days until you should do something in it next? ("3 days to do something", not
// "3d ago"). daysDesc is the union of the area's practice ticks, newest first.
function areaCheckin(daysDesc, cadence) {
  const today = dayKey(new Date());
  const cad = parseCadence(cadence);
  if (!cad) return null;
  const lastDone = daysDesc[0] || null;
  // Only the overdue (slipping) state carries a message now - the day-by-day
  // countdown ("2 days to do something") was noise. The render shows the line
  // only when status is 'slipping'; the other labels are kept for completeness.
  if (cad.unit === 'd') {
    if (!lastDone) return { status: 'ontrack', label: '' };
    const remaining = cad.n - daysBetweenStr(lastDone, today);
    if (remaining >= 0) return { status: 'ontrack', label: '' };
    const over = -remaining;
    return { status: 'slipping', label: over === 1 ? 'a day overdue' : `${over} days overdue` };
  }
  // A "N times a week" area: only nag when the week's gone by with none done.
  const weekCount = daysDesc.filter((d) => daysBetweenStr(d, today) < 7).length;
  if (weekCount > 0) return { status: 'ontrack', label: '' };
  return { status: 'slipping', label: 'overdue this week' };
}
// A cadence said as a plain phrase, for any value (presets or a custom one).
function areaCadLabel(v) {
  const c = parseCadence(v); if (!c) return v || '';
  if (c.unit === 'd') { if (c.n === 1) return 'every day'; if (c.n === 2) return 'every other day'; if (c.n % 7 === 0) { const w = c.n / 7; return w === 1 ? 'every week' : `every ${w} weeks`; } return `every ${c.n} days`; }
  return c.n === 1 ? 'once a week' : c.n === 2 ? 'twice a week' : `${c.n}× a week`;
}
function dailyStreak(daysDesc, today) {
  if (!daysDesc.length) return 0;
  if (daysBetweenStr(daysDesc[0], today) > 1) return 0;
  let s = 1; for (let i = 1; i < daysDesc.length; i++) { if (daysBetweenStr(daysDesc[i], daysDesc[i - 1]) === 1) s++; else break; } return s;
}
function cadenceStreak(daysDesc, cad, today) {
  if (!daysDesc.length || daysBetweenStr(daysDesc[0], today) > cad.n) return 0;
  let s = 1; for (let i = 1; i < daysDesc.length; i++) { if (daysBetweenStr(daysDesc[i], daysDesc[i - 1]) <= cad.n) s++; else break; } return s;
}
function savePracticeMarks() { if (!state.practices) return; api('/api/kv/practice_marks', { method: 'PUT', body: JSON.stringify({ value: JSON.stringify(state.practices.marks) }) }).catch(() => {}); }
const practiceMarked = (id, day) => !!(state.practices && state.practices.marks[`${id}:${day}`]);
function rerenderPractices() { const v = state.view.type; if (v === 'home') renderHome(); else if (v === 'practices') renderPractices(); else if (v === 'tracker') renderTracker(); else if (v === 'today') renderToday(); else if (v === 'toolbox') renderToolbox(); else if (v === 'practicecard') renderPracticeCard(); }
// Practices and Tracker are ONE tool now. Every data-open-practices link lands on
