function practiceToggle(id, day) { const P = state.practices; if (!P) return; const k = `${id}:${day}`; if (P.marks[k]) delete P.marks[k]; else P.marks[k] = 1; savePracticeMarks(); rerenderPractices(); }
// Inline rename from the merged Practices tool: click the name, type, Enter/blur.
async function renamePractice(id, title) {
  const a = (state.practices && state.practices.activities || []).find((x) => String(x.id) === String(id)); if (!a) return;
  const clean = String(title || '').replace(/\s+/g, ' ').trim();
  if (!clean || clean === a.title) return;   // empty or unchanged: leave it be
  a.title = clean;
  try { await api('/api/activities/' + id, { method: 'PATCH', body: JSON.stringify({ title: clean }) }); }
  catch (e) { toast(e.message); }
  rerenderPractices();
}
function practiceStreak(id) {
  if (!state.practices) return 0;
  const a = (state.practices.activities || []).find((x) => String(x.id) === String(id));
  if (a && a.avoid) return avoidStreak(a);
  let s = 0; const d = new Date(); for (;;) { if (state.practices.marks[`${id}:${dayKey(d)}`]) { s++; d.setDate(d.getDate() - 1); } else break; } return s;
}
// An "avoiding" habit: the streak is consecutive CLEAN days (no slip) since you
// started, ending the moment you log a slip. So the flame rewards staying off it.
function avoidStreak(a) {
  const P = state.practices; if (!P) return 0;
  const since = a.avoid_since || null;
  let s = 0; const d = new Date();
  for (let i = 0; i < 3660; i++) { const k = dayKey(d); if (P.marks[`${a.id}:${k}`]) break; if (since && k < since) break; s++; d.setDate(d.getDate() - 1); }
  return s;
}
async function practiceAdd(area, title) {
  title = (title || '').trim(); if (!title || !state.practices) return;
  try { const a = await api('/api/activities', { method: 'POST', body: JSON.stringify({ area: area || undefined, title: title.slice(0, 80), duration: 30 }) }); state.practices.activities.push(a); rerenderPractices(); }
  catch (e) { toast(e.message); }
}
async function practiceDelete(id) {
  const acts = (state.practices && state.practices.activities) || [];
  const a = acts.find((x) => String(x.id) === String(id));
  // Snapshot both the practice and its ticked days, so Undo can rebuild the
  // streak history (marks are keyed by id, and a re-created practice gets a new
  // one, so we remap them across).
  const snap = a ? { ...a } : null;
  const marks = (state.practices && state.practices.marks) || {};
  const keptDays = Object.keys(marks).filter((k) => k.startsWith(id + ':')).map((k) => k.slice((id + ':').length));
  try {
    await api('/api/activities/' + id, { method: 'DELETE' });
    if (state.practices) state.practices.activities = acts.filter((x) => String(x.id) !== String(id));
    keptDays.forEach((day) => { delete marks[`${id}:${day}`]; });
    savePracticeMarks();
    if (state.practiceEdit && String(state.practiceEdit.id) === String(id)) { state.practiceEdit = null; const host = document.getElementById('prac-editor-host'); if (host) host.innerHTML = ''; }
    rerenderPractices();
    toast(snap ? `Deleted "${snap.title}"` : 'Practice deleted', snap ? () => undoPracticeDelete(snap, keptDays) : null);
  } catch (e) { toast(e.message); }
}
async function undoPracticeDelete(snap, keptDays) {
  const body = {
    title: snap.title, duration: snap.duration || 30, url: snap.url || undefined, lane: snap.lane,
    area: snap.area || undefined, note: snap.note || undefined, video: snap.video || undefined,
    timed: !!snap.timed, tracked: !!snap.tracked, days: snap.days || undefined,
    time_min: snap.time_min != null ? snap.time_min : undefined, cadence: snap.cadence || undefined,
    priority: snap.priority || undefined, avoid: !!snap.avoid, avoidSince: snap.avoid_since || undefined, meta: snap.meta || undefined,
  };
  try {
    const na = await api('/api/activities', { method: 'POST', body: JSON.stringify(body) });
    state.practices.activities.push(na);
    const marks = state.practices.marks || (state.practices.marks = {});
    keptDays.forEach((day) => { marks[`${na.id}:${day}`] = 1; });
    savePracticeMarks();
    rerenderPractices();
    toast('Restored');
  } catch (e) { toast(e.message); }
}
// Practices grouped by Page (falling back to the legacy lane label for any
// not yet filed under an area). withWeek adds the 7-day dot row + streak (Home);
// the management list (withWeek=false) adds a schedule summary + an edit button.
function practicesGroups(withWeek) {
  const P = state.practices; const today = dayKey(new Date()); const days = trackerLast7(); const dow = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
  const laneOf = (k) => (P.lanes || []).find((l) => l.key === k) || { label: k, hue: 0 };
  // Group key: area id when set, else `lane:<lane>`. Carry a label + hue for each.
  const groups = new Map();
  (P.activities || []).forEach((a) => {
    const ar = practiceArea(a);
    const key = ar ? ar.id : `lane:${a.lane}`;
    if (!groups.has(key)) groups.set(key, { label: ar ? (ar.title || 'Untitled') : laneOf(a.lane).label, hue: ar ? hueOf(ar) : laneOf(a.lane).hue, items: [] });
    groups.get(key).items.push(a);
  });
  const ordered = [...groups.values()].sort((a, b) => a.label.localeCompare(b.label));
  return ordered.map((g) => {
    const rows = g.items.map((a) => {
      const len = (a.timed && a.duration) ? `<span class="prc-sched">${a.duration} min</span>` : '';
      const badges = `${a.avoid ? '<span class="t2-avoidtag">avoiding</span>' : ''}${a.video ? '<span class="prc-badge">🎥</span>' : ''}${!a.timed ? '<span class="prc-badge dim" title="A habit — not on the day">habit</span>' : ''}`;
      return `<div class="prc-row prc-row-click ${a.avoid ? 't2-avoid' : ''}" data-prc-open="${a.id}" role="button" tabindex="0" title="Open ${esc(a.title)}">
        <button class="trk-tick ${practiceMarked(a.id, today) ? 'on' : ''} ${a.avoid ? 't2-tick-slip' : ''}" data-prc-tick="${a.id}" title="${a.avoid ? (practiceMarked(a.id, today) ? 'Slipped today - tap to undo' : 'Tap if you slipped today') : 'Done today'}">${a.avoid ? '✕' : '✓'}</button>
        <span class="prc-name prc-name-link">${esc(a.title)}${badges}${withWeek ? '' : len}</span>
        ${withWeek ? `<span class="trk-week">${days.map((d) => `<span class="trk-dot ${practiceMarked(a.id, d) ? (a.avoid ? 'slip' : 'on') : ''} ${d === today ? 'today' : ''}" data-prc-day="${a.id}:${d}" title="${d}"><i>${dow[new Date(d + 'T00:00').getDay()]}</i></span>`).join('')}</span>${(() => { const s = practiceStreak(a.id); return s > 1 ? `<span class="trk-streak">🔥 ${s}${a.avoid ? ' clean' : ''}</span>` : ''; })()}` : `<button class="prc-edit" data-prc-edit="${a.id}" title="Edit practice">✎</button>`}
        <button class="trk-del" data-prc-del="${a.id}" title="Remove practice">×</button>
      </div>`;
    }).join('');
    return `<div class="prc-group"><div class="prc-lane" style="--h:${g.hue}"><span class="prc-lane-dot"></span>${esc(g.label)}</div>${rows}</div>`;
  }).join('');
}
