  if (s.done && s.activity_id) { const k = `${s.activity_id}:${T.day}`; delete state.practices.marks[k]; savePracticeMarks(); }
  try { await api('/api/slots/' + slotId, { method: 'DELETE' }); } catch (e) { toast(e.message); }
