const mailQuadOf = (o) => {
  if (!o) return 'inbox';
  const e = mailQuadEntry(mailFileKey(o));
  if (e && e.q) return normQuad(e.q);   // hand-filed wins
  if (o.flagged) return 'important';   // a previously-starred email counts as Important
  return 'inbox';
};
