  const hasStatus = !!(state.friendStatus && Array.isArray(state.friendStatus.online));
  const friendsSorted = friendsByRecency((d.friends || []).map((f) => ({ ...f, online: hasStatus ? onSet.has(f.id) : !!f.online })));
