  const af = state.contactsArea;
  const match = (c) => {
    if (af && !blockAreas(c).includes(af)) return false;
    if (!q) return true; const p = c.props || {}; return [c.title, p.email, p.phone].some((v) => (v || '').toLowerCase().includes(q));
  };
