    practices: mir.practices || [],
    tasksDone: s.done.slice(0, 200).map((t) => ({ id: t.id, title: t.title, area: t.props.area, goal: t.props.goal || null, priority: t.props.priority || null, created: t.created_at || null, at: t.updated_at || null })),
