      for (const aid of Object.keys(p.wheel)) { const now = Math.min(p.wheel[aid] || 0, 5), was = Math.min(prev.wheel[aid] || 0, 5); if (now && was && now !== was && nm(aid)) deltas.push({ aid, d: now - was, now, was }); }
      deltas.sort((a, b) => b.d - a.d);
