      pts.push(['📊', `Life balance sitting at <b>${avg}/5</b>${pd ? ` <span class="rr-key-d ${pd > 0 ? 'up' : 'down'}">${pd > 0 ? '▲' : '▼'}${Math.abs(pd)} vs last ${period}</span>` : ''}`]);
