  if (s && !/[.!?…"'”’)\]]$/.test(s)) { const cut = Math.max(s.lastIndexOf('.'), s.lastIndexOf('!'), s.lastIndexOf('?'), s.lastIndexOf('…')); if (cut > 40) s = s.slice(0, cut + 1); }
