    return { id: d.id, title: d.title, area: d.area || lp.area || null, goal: d.goal || lp.goal || null,
      priority: d.priority || lp.priority || null, created: d.created || (live && live.created_at) || null, at: d.at || (live && live.updated_at) || null };
