  for (const tk of (state.allTasks || []).filter((x) => x.props && x.props.note === n.id && !x.props.done)) rows.push(nxOpenRow('✓', tk.title, 'Task', '', `data-open-task="${tk.id}"`, `data-note-task-unlink="${tk.id}"`));
