  if (!Array.isArray(state.tables)) { state.tables = []; api('/api/blocks?kind=table').then((r) => { state.tables = r || []; rr(); }).catch(() => {}); }
  if (!Array.isArray(state.noteEvents)) loadNoteEvents();
